            var typeRawValue = FieldTypeValueConverter.ToJsonValue(fieldsInnerInner.Type);
            writer.WriteString("type", typeRawValue);

            if (fieldsInnerInner.RequiredOption.IsSet)
                writer.WriteBoolean("required", fieldsInnerInner.RequiredOption.Value!.Value);

            if (fieldsInnerInner.LabelOption.IsSet)
                writer.WriteString("label", fieldsInnerInner.Label);

            if (fieldsInnerInner.ValueOption.IsSet)
            {
                writer.WritePropertyName("value");
                if (fieldsInnerInner.Type == FieldType.Checkbox)

                    writer.WriteStringValue(SignWell.Sdk.Embedded.SignWellValues.NormalizeCheckbox(fieldsInnerInner.Value!));

                else

                    JsonSerializer.Serialize(writer, fieldsInnerInner.Value, jsonSerializerOptions);
            }
            if (fieldsInnerInner.ApiIdOption.IsSet)
                writer.WriteString("api_id", fieldsInnerInner.ApiId);

            if (fieldsInnerInner.NameOption.IsSet)
                writer.WriteString("name", fieldsInnerInner.Name);

            if (fieldsInnerInner.ValidationOption.IsSet)
            {
                var validationRawValue = TextValidationValueConverter.ToJsonValue(fieldsInnerInner.Validation!.Value);
                writer.WriteString("validation", validationRawValue);
            }
            if (fieldsInnerInner.FixedWidthOption.IsSet)
                writer.WriteBoolean("fixed_width", fieldsInnerInner.FixedWidthOption.Value!.Value);

            if (fieldsInnerInner.LockSignDateOption.IsSet)
                writer.WriteBoolean("lock_sign_date", fieldsInnerInner.LockSignDateOption.Value!.Value);

            if (fieldsInnerInner.DateFormatOption.IsSet)
            {
                var dateFormatRawValue = DateFormatValueConverter.ToJsonValue(fieldsInnerInner.DateFormat!.Value);
                writer.WriteString("date_format", dateFormatRawValue);
            }
            if (fieldsInnerInner.HeightOption.IsSet)
                writer.WriteNumber("height", fieldsInnerInner.HeightOption.Value!.Value);

            if (fieldsInnerInner.WidthOption.IsSet)
                writer.WriteNumber("width", fieldsInnerInner.WidthOption.Value!.Value);

            if (fieldsInnerInner.OptionsOption.IsSet)
            {
                writer.WritePropertyName("options");
                JsonSerializer.Serialize(writer, fieldsInnerInner.Options, jsonSerializerOptions);
            }
            if (fieldsInnerInner.DefaultOptionOption.IsSet)
                writer.WriteString("default_option", fieldsInnerInner.DefaultOption);

            if (fieldsInnerInner.AllowOtherOption.IsSet)
                writer.WriteBoolean("allow_other", fieldsInnerInner.AllowOtherOption.Value!.Value);
        }
    }
}
